// Read all incoming items, tolerate either {output: {...}} or {...}
const inItems = $input.all().map(i => i.json.output ?? i.json);

// Helper: normalize strings safely
const s = (v) => (typeof v === 'string' ? v.trim() : '');

// Render one research record to plain text suitable for X
function renderX(r) {
  const title = s(r.headline) || s(r.tool_name) || 'Update';
  const why = s(r.why_it_matters);
  const points = Array.isArray(r.key_points) ? r.key_points.filter(Boolean).map(p => `• ${p}`).join('\n') : '';
  const url = s(r.link) || s(r.url) || '';

  // No emojis, no em dashes, short lines
  let out = `${title}`;
  if (why) out += `\n${why}`;
  if (points) out += `\n${points}`;
  if (url) out += `\nExplore → ${url}`;

  // Trim to something X-safe; leave hard limit to the X Composer node
  return out.trim();
}

// Build one output item per input item
const out = inItems.map(r => ({
  json: {
    x_text: renderX(r),   // what your X Post Composer should read
    research: r           // keep full structured data if later nodes need it
  }
}));

return out;

// Access all input items (each one is a video)
const items = $input.all();

// For each video item, join the captions from data[]
const result = items.map(item => {
  const data = item.json.data;

  // Safely join text only if data is an array
  const fullCaption = Array.isArray(data)
    ? data.map(d => d.text).join(' ')
    : '';

  return {
    json: {
      full_caption: fullCaption
    }
  };
});

return result;

let raw = ($input.first().json.output || '').toString().trim();

// 1) Clean formatting
let cleaned = raw
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')   // collapse >2 breaks
  .replace(/\s+$/gm, '')        
  .trim();

// 2) Enforce 280 chars
if (cleaned.length > 280) {
  cleaned = cleaned.slice(0, 277) + '…';
}

// 3) Build review text
const review_text = [
  "Proposed X Post:",
  cleaned,
  "",
  `Characters: ${cleaned.length} / 280`
].join('\n');

// 4) Image prompt seed
const image_prompt = cleaned
  .replace(/\s+/g, ' ')
  .slice(0, 160);

return [{
  json: {
    tweet_text: cleaned,
    review_text,
    image_prompt
  }
}];
